#[inline(never)]
fn decimal128_ratio_to_float64(value: i128, divisor: u128, divisor_bits: u32) -> f64 {
    let magnitude = value.unsigned_abs();
    // Keep 55 or 56 quotient bits: 53 significand bits, a round bit and a
    // sticky bit. For scales 1..=21 the shifted numerator fits in u128.
    let shift = 128 - magnitude.leading_zeros() as i32 - divisor_bits as i32 - 55;
    let (numerator, denominator) = if shift >= 0 {
        (magnitude, divisor << shift)
    } else {
        (magnitude << -shift, divisor)
    };
    let quotient = numerator / denominator;
    let remainder = numerator % denominator;
    let rounded = ((quotient as i64) | (remainder != 0) as i64) as f64;
    // All Decimal128 ratios here are normal Float64 values. Scaling by an
    // exact power of two preserves the integer conversion's rounding.
    let result = rounded * f64::from_bits(((1023 + shift) as u64) << 52);
    if value < 0 { -result } else { result }
}

fn main() {
    let mut checked = 0_u64;
    let mut seed = 818_818_191_u128;
    for scale in 23..=31 {
        let divisor = 5_u128.pow(scale);
        let bits = 128 - divisor.leading_zeros();
        assert!(bits <= 72);
        let factor = f64::from_bits(((1023 - scale) as u64) << 52);
        let mut check = |value: i128| {
            let actual = decimal128_ratio_to_float64(value, divisor, bits) * factor;
            let expected = format!("{value}e-{scale}").parse::<f64>().unwrap();
            assert_eq!(actual.to_bits(), expected.to_bits(), "value={value}, scale={scale}");
            checked += 1;
        };
        check(i128::MIN); check(i128::MAX);
        for value in -262144_i128..=262144 { check(value); }
        for shift in 0..127 {
            let value = 1_i128 << shift;
            for value in [value-1, value, value+1] { check(value); check(-value); }
        }
        for significand in [(1_i128<<53)-1, (1_i128<<53)+1, (1_i128<<53)+3] {
            let mut value = significand * divisor as i128;
            loop {
                for value in [value-1, value, value+1] { check(value); check(-value); }
                let Some(next) = value.checked_mul(2) else { break; };
                value = next;
            }
        }
        for _ in 0..65536 {
            seed ^= seed << 13; seed ^= seed >> 17; seed ^= seed << 43;
            check(seed as i128);
        }
    }
    println!("{checked} exact Float64 comparisons passed");
}
